    {'file': 'Games.lua', 'line': 1710, 'value': '﴿فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ وَهُوَ الْفَتَّاحُ الْعَلِيمُ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنْجَبِيلًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿أَلَمْ تَكُنْ آيَاتِي تُتْلَىٰ عَلَيْكُمْ فَكُنْتُمْ بِهَا تُكَذِّبُونَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿ارْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُمْ بِجُنُودٍ لَا قِبَلَ لَهُمْ بِهَا وَلَنُخْرِجَنَّهُمْ مِنْهَا أَذِلَّةً وَهُمْ صَاغِرُونَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿الَّذِينَ يُوفُونَ بِعَهْدِ اللَّهِ وَلَا يَنْقُضُونَ الْمِيثَاقَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَامٌ وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿ادْخُلُوا الْجَنَّةَ بِمَا كُنْتُمْ تَعْمَلُونَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿لَكُمْ دِينُكُمْ وَلِيَ دِينِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَمَا يَسْتَوِي الْأَعْمَىٰ وَالْبَصِيرُ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿ذَٰلِكَ وَمَنْ يُعَظِّمْ شَعَائِرَ اللَّهِ فَإِنَّهَا مِنْ تَقْوَى الْقُلُوبِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَاللَّهُ أَعْلَمُ بِأَعْدَائِكُمْ وَكَفَىٰ بِاللَّهِ وَلِيًّا وَكَفَىٰ بِاللَّهِ نَصِيرًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿إِنَّ اللَّهَ لَا يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وُجُوهٌ يَوْمَئِذٍ مُسْفِرَةٌ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿فَلْيَنْظُرِ الْإِنْسَانُ مِمَّ خُلِقَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُمْ مِنْ فَضْلِهِ إِنَّهُ غَفُورٌ شَكُورٌ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ وَإِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿مَنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿قَالَتْ إِنِّي أَعُوذُ بِالرَّحْمَٰنِ مِنْكَ إِنْ كُنْتَ تَقِيًّا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿قُلْ إِنَّ الْأَمْرَ كُلَّهُ لِلَّهِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿إِنَّ كَيْدَ الشَّيْطَانِ كَانَ ضَعِيفًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَقَضَيْنَا إِلَيْهِ ذَٰلِكَ الْأَمْرَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿إِنَّ الْمُصَّدِّقِينَ وَالْمُصَّدِّقَاتِ وَأَقْرَضُوا اللَّهَ قَرْضًا حَسَنًا يُضَاعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَأَقِمِ الصَّلَاةَ إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُسْتَقِيمًا﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿إِنَّ الْمُتَّقِينَ فِي مَقَامٍ أَمِينٍ﴾'},
    {'file': 'Games.lua', 'line': 1710, 'value': '﴿كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ ثُمَّ إِلَيْنَا تُرْجَعُونَ﴾'},
