    {'file': 'Games.lua', 'line': 7086, 'value': '\nكم جزء يحتوي القران الكريم؟\n\n1- 60\n2- 70\n3- 30 \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7095, 'value': '\nمن هوه اغنى رئيس في العالم؟\n\n1- ترامب\n2- اوباما\n3- بوتين  \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7105, 'value': '\nمن هوه مؤسس شركه ابل العالميه \n\n1-لاري بايج \n2- بيا غايتز\n3- ستيف جوبر\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7114, 'value': '\nماهي عاصمه فرنسا؟\n\n1- باريس \n2- لوين \n3- موسكو \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7123, 'value': '\nماعدد دول العربيه التي توجد في افريقيا \n\n1- 10 \n2- 17\n3- 9\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7132, 'value': '\nماهو الحيوان الذي يحمل 50 فوق وزنه؟\n1-الفيل\n2- النمل  \n3- الثور\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7140, 'value': '\nماذا يوجد بيني وبينك؟  \n1- الضل\n2- الاخلاق\n3-حرف الواو  \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7148, 'value': '\nماهو الشيء النبات ينبت للانسان بلا بذر؟\n1-الاضافر \n2- الاسنان\n3- الشعر\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7156, 'value': '\nم̷ـــِْن هو اول الرسول الى الارض؟\n1- ادم\n2- نوح\n3-ابراهيم \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7164, 'value': '\nما هو الشّيء الذي يستطيع المشي بدون أرجل والبكاء بدون أعين؟\n1- سحاب\n2- بئر\n3- نهر\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7172, 'value': '\nما الشيء الذي نمتلكه , لكنّ غيرنا يستعمله أكثر منّا؟\n1- العمر\n2- ساعه\n3- الاسم\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7180, 'value': '\nاصفر اللون سارق عقول اهل الكون وحارمهم لذيذ النوم\n1- نحاس\n2- الماس\n3- ذهب\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7188, 'value': '\nفي الليل ثلاثة لكنه في النهار واحده فما هو\n 1- حرف الباء\n 2- حرف الام \n3- حرف الراء\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7196, 'value': '\nعلى قدر اصل العزم تأتي؟\n1- العزائم \n2- المكارم\n3- المبائب\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7205, 'value': '\nماهي جمع كلمه انسه ؟\n1- سيدات\n2- انسات \n3- قوانص\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7213, 'value': '\nاله اتسعلمت قديما في الحروب؟\n1- الصاروخ\n2- المسدس\n3- المنجنيق \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7221, 'value': '\nتقع لبنان في قاره؟\n1- افريقيا \n2- اسيا  \n3- امركيا الشماليه\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7230, 'value': '\n1- ماهو الحيوان الذي يلقب بملك الغابه؟\n1-الفيل\n2- الاسد \n3- النمر\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7238, 'value': '\nكم صفرا للمليون ؟\n1- 4 \n2- 3\n3-6\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7246, 'value': '\nما اسم صغير الحصان؟\n1- مهر  \n2- جرو\n3- عجل\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7254, 'value': '\nما الحيوان الذي ينام واحدى عينه مفتوحه؟\n\n1- القرش\n2- الدلفين \n3- الثعلب\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7263, 'value': '\nماهي القاره التي تلقب بالقاره العجوز؟\n\n1- امريكا الشماليه \n2- امريكا الجنوبيه\n3- افريقيا \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7272, 'value': '\nما اسم المعدن الموجود فيي الحاله السائله \n\n1- النحاس \n2- الحديد\n3- الزئبق \n \n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7281, 'value': '\nماهي عاصمه انجلترا؟\n1- لندن  \n2- لفرسول\n3- تركيا\n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7289, 'value': '\nماهو الشئ الذي برأسه سبع فتحات\n\n1- الهاتف\n2- التلفاز\n3- الانسان \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7298, 'value': '\nماهي عاصمه اليابان ؟\n1- بانكول\n2- نيو دلهي\n3- طوكيو \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'Games.lua', 'line': 7306, 'value': '\nمن هي زوجه الرسول الاكبر منه سنآ؟\n\n1- حفضه\n2- زينب \n3- خديجه \n\n⇜ ارسل الجواب الصحيح\n'},
    {'file': 'libs/dkjson.lua', 'line': 6, 'value': '\n\nDavid Kolf\'s JSON module for Lua 5.1/5.2\n========================================\n*Version 2.4*\nIn the default configuration this module writes no global values, not even\nthe module table. Import it using\n    json = require ("dkjson")\nIn environments where `require` or a similiar function are not available\nand you cannot receive the return value of the module, you can set the\noption `register_global_module_table` to `true`.  The module table will\nthen be saved in the global variable with the name given by the option\n`global_module_name`.\nExported functions and values:\n`json.encode (object [, state])`\n--------------------------------\nCreate a string representing the object. `Object` can be a table,\na string, a number, a boolean, `nil`, `json.null` or any object with\na function `__tojson` in its metatable. A table can only use strings\nand numbers as keys and its values have to be valid objects as\nwell. It raises an error for any invalid data types or reference\ncycles.\n`state` is an optional table with the following fields:\n  - `indent`  \n    When `indent` (a boolean) is set, the created string will contain\n    newlines and indentations. Otherwise it will be one long line.\n  - `keyorder`  \n    `keyorder` is an array to specify the ordering of keys in the\n    encoded output. If an object has keys which are not in this array\n    they are written after the sorted keys.\n  - `level`  \n    This is the initial level of indentation used when `indent` is\n    set. For each level two spaces are added. When absent it is set\n    to 0.\n  - `buffer`  \n    `buffer` is an array to store the strings for the result so they\n    can be concatenated at once. When it isn\'t given, the encode\n    function will create it temporary and will return the\n    concatenated result.\n  - `bufferlen`  \n    When `bufferlen` is set, it has to be the index of the last\n    element of `buffer`.\n  - `tables`  \n    `tables` is a set to detect reference cycles. It is created\n    temporary when absent. Every table that is currently processed\n    is used as key, the value is `true`.\n\nWhen `state.buffer` was set, the return value will be `true` on\nsuccess. Without `state.buffer` the return value will be a string.\n\n`json.decode (string [, position [, null]])`\n--------------------------------------------\n\nDecode `string` starting at `position` or at 1 if `position` was\nomitted.\n\n`null` is an optional value to be returned for null values. The\ndefault is `nil`, but you could set it to `json.null` or any other\nvalue.\n\nThe return values are the object or `nil`, the position of the next\ncharacter that doesn\'t belong to the object, and in case of errors\nan error message.\nTwo metatables are created. Every array or object that is decoded gets\na metatable with the `__jsontype` field set to either `array` or\n`object`. If you want to provide your own metatables use the syntax\n    json.decode (string, position, null, objectmeta, arraymeta)\nTo prevent the assigning of metatables pass `nil`:\n    json.decode (string, position, null, nil)\n`<metatable>.__jsonorder`\n-------------------------\n`__jsonorder` can overwrite the `keyorder` for a specific table.\n`<metatable>.__jsontype`\n------------------------\n`__jsontype` can be either `"array"` or `"object"`. This value is only\nchecked for empty tables. (The default for empty tables is `"array"`).\n`<metatable>.__tojson (self, state)`\n------------------------------------\nYou can provide your own `__tojson` function in a metatable. In this\nfunction you can either add directly to the buffer and return true,\nor you can return a string. On errors nil and a message should be\nreturned.\n`json.null`\n-----------\nYou can use this value for setting explicit `null` values.\n`json.version`\n--------------\nSet to `"dkjson 2.4"`.\n`json.quotestring (string)`\n---------------------------\nQuote a UTF-8 string and escape critical characters using JSON\nescape sequences. This function is only necessary when you build\nyour own `__tojson` functions.\n`json.addnewline (state)`\n-------------------------\nWhen `state.indent` is set, add a newline to `state.buffer` and spaces\naccording to `state.level`.\nLPeg support\n------------\nWhen the local configuration variable `always_try_using_lpeg` is set,\nthis module tries to load LPeg to replace the `decode` function. The\nspeed increase is significant. You can get the LPeg module at\n  <http://www.inf.puc-rio.br/~roberto/lpeg/>.\nWhen LPeg couldn\'t be loaded, the pure Lua functions stay active.\n\nIn case you don\'t want this module to require LPeg on its own,\ndisable the option `always_try_using_lpeg` in the options section at\nthe top of the module.\nIn this case you can later load LPeg support using\n### `json.use_lpeg ()`\nRequire the LPeg module and replace the functions `quotestring` and\nand `decode` with functions that use LPeg patterns.\nThis function returns the module table, so you can load the module\nusing:\n    json = require "dkjson".use_lpeg()\nAlternatively you can use `pcall` so the JSON module still works when\nLPeg isn\'t found.\n\n    json = require "dkjson"\n    pcall (json.use_lpeg)\n\n### `json.using_lpeg`\n\nThis variable is set to `true` when LPeg was loaded successfully.\n\n---------------------------------------------------------------------\n\nContact\n-------\n\nYou can contact the author by sending an e-mail to \'david\' at the\ndomain \'dkolf.de\'.\n\n---------------------------------------------------------------------\n\n*Copyright (C) 2010-2013 David Heiko Kolf*\n\nPermission is hereby granted, free of charge, to any person obtaining\na copy of this software and associated documentation files (the\n"Software"), to deal in the Software without restriction, including\nwithout limitation the rights to use, copy, modify, merge, publish,\ndistribute, sublicense, and/or sell copies of the Software, and to\npermit persons to whom the Software is furnished to do so, subject to\nthe following conditions:\n\nThe above copyright notice and this permission notice shall be\nincluded in all copies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND,\nEXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF\nMERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND\nNONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS\nBE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN\nACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN\nCONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n<!-- This documentation can be parsed using Markdown to generate HTML.\n     The source code is enclosed in a HTML comment so it won\'t be displayed\n     by browsers, but it should be removed from the final HTML file as\n     it isn\'t a valid HTML comment (and wastes space).\n  -->\n\n<!--'},
