    {'file': 'libs/url.lua', 'line': 1, 'value': '\nCopyright 2004-2007 Diego Nehab. \nPermission is hereby granted, free of charge, to any person\nobtaining a copy of this software and associated documentation\nfiles (the "Software"), to deal in the Software without\nrestriction, including without limitation the rights to use,\ncopy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the\nSoftware is furnished to do so, subject to the following\nconditions:\n\nThe above copyright notice and this permission notice shall be\nincluded in all copies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND,\nEXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES\nOF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND\nNONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\nHOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY,\nWHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING\nFROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR\nOTHER DEALINGS IN THE SOFTWARE.\n'},
    {'file': 'libs/utf8.lua', 'line': 23, 'value': '\nCopyright (c) 2006-2007, Kyle Smith\nAll rights reserved.\n\nContributors:\n\tAlimov Stepan\n\nRedistribution and use in source and binary forms, with or without\nmodification, are permitted provided that the following conditions are met:\n\n    * Redistributions of source code must retain the above copyright notice,\n      this list of conditions and the following disclaimer.\n    * Redistributions in binary form must reproduce the above copyright\n      notice, this list of conditions and the following disclaimer in the\n      documentation and/or other materials provided with the distribution.\n    * Neither the name of the author nor the names of its contributors may be\n      used to endorse or promote products derived from this software without\n      specific prior written permission.\n\nTHIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS"\nAND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE\nIMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE\nDISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT OWNER OR CONTRIBUTORS BE LIABLE\nFOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL\nDAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR\nSERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER\nCAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY,\nOR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE\nOF THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.\n--'},
    {'file': 'libs/utf8.lua', 'line': 240, 'value': '\n-- replace UTF-8 characters based on a mapping table\nlocal function utf8replace (s, mapping)\n\t-- argument checking\n\tif type(s) ~= "string" then\n\t\terror("bad argument #1 to \'utf8replace\' (string expected, got ".. type(s).. ")")\n\tend\n\tif type(mapping) ~= "table" then\n\t\terror("bad argument #2 to \'utf8replace\' (table expected, got ".. type(mapping).. ")")\n\tend\n\n\tlocal pos = 1\n\tlocal bytes = len(s)\n\tlocal charbytes\n\tlocal newstr = ""\n\n\twhile pos <= bytes do\n\t\tcharbytes = utf8charbytes(s, pos)\n\t\tlocal c = sub(s, pos, pos + charbytes - 1)\n\n\t\tnewstr = newstr .. (mapping[c] or c)\n\n\t\tpos = pos + charbytes\n\tend\n\n\treturn newstr\nend\n\n\n-- identical to string.upper except it knows about unicode simple case conversions\nlocal function utf8upper (s)\n\treturn utf8replace(s, utf8_lc_uc)\nend\n\n-- identical to string.lower except it knows about unicode simple case conversions\nlocal function utf8lower (s)\n\treturn utf8replace(s, utf8_uc_lc)\nend\n'},
    {'file': 'libs/utf8.lua', 'line': 560, 'value': '\n-- utf8sub with extra argument, and extra result value\nlocal function utf8subWithBytes (s, i, j, sb)\n\t-- argument defaults\n\tj = j or -1\n\n\tlocal pos = sb or 1\n\tlocal bytes = len(s)\n\tlocal length = 0\n\n\t-- only set l if i or j is negative\n\tlocal l = (i >= 0 and j >= 0) or utf8len(s)\n\tlocal startChar = (i >= 0) and i or l + i + 1\n\tlocal endChar   = (j >= 0) and j or l + j + 1\n\n\t-- can\'t have start before end!\n\tif startChar > endChar then\n\t\treturn ""\n\tend\n\n\t-- byte offsets to pass to string.sub\n\tlocal startByte,endByte = 1,bytes\n\n\twhile pos <= bytes do\n\t\tlength = length + 1\n\n\t\tif length == startChar then\n\t\t\tstartByte = pos\n\t\tend\n\n\t\tpos = pos + utf8charbytes(s, pos)\n\n\t\tif length == endChar then\n\t\t\tendByte = pos - 1\n\t\t\tbreak\n\t\tend\n\tend\n\n\tif startChar > length then startByte = bytes+1   end\n\tif endChar   < 1      then endByte   = 0         end\n\n\treturn sub(s, startByte, endByte), endByte + 1\nend\n'},
    {'file': 'libs/utf8.lua', 'line': 909, 'value': " if lastPos < self.str then\n\t\t\t\t\tprint('last byte', lastByte)\n\t\t\t\t\tch, lastByte = utf8subWithBytes(str, 1, self.str - lastPos - 1, lastByte)\n\t\t\t\t\tch, lastByte = utf8subWithBytes(str, 1, 1, lastByte)\n\t\t\t\t\tlastByte = lastByte - 1\n\t\t\t\telse\n\t\t\t\t\tch, lastByte = utf8subWithBytes(str, self.str, self.str)\n\t\t\t\tend\n\t\t\t\tlastPos = self.str "},
    {'file': 'rdood.lua', 'line': 101, 'value': '\n*⇜ حلو , الحين ارسل جواب الرد*\n*⇜ ( نص,صوره,فيديو,متحركه,بصمه,اغنيه )*\nٴ*⋆┄─┄─┄─┄┄─┄─┄─┄─┄┄⋆*\n `{اليوزر}` *↬ يوزر المستخدم*\n `{الرسائل}` *↬ عدد الرسائل*\n `{الاسم}` *↬ اسم المستخدم*\n `{الايدي}` *↬ ايدي المستخدم*\n `{الرتبه}` *↬ رتبة المستخدم*\n `{التعديل}` *↬ عدد التعديلات*\n\n'},
    {'file': 'rdood.lua', 'line': 2902, 'value': '\n*⇜ تم تـرتيب الاوامـر بالشكـل التالـي :*\nٴ*⋆┄─┄─┄─┄┄─┄─┄─┄─┄┄⋆*\n⇜ ايدي - ا \n⇜ رفع مميز - م \n⇜ رفع ادمن - اد \n⇜ رفع مدير - مد \n⇜ رفع منشئ - منش \n⇜ رفع منشئ الاساسي - اس  \n⇜ رفع مطور - مط \n⇜ رفع مطور ثانوي - ثانوي \n⇜ تنزيل الكل بالرد - تن \n⇜ تعطيل الايدي بالصوره - تعط \n⇜ تفعيل الايدي بالصوره - تفع \n⇜ تغيير الايدي - تغ \n⇜ تنزيل جميع الرتب - تنز \n⇜ قفل الاشعارات - قق \n⇜ فتح الاشعارات - فف \n⇜ الرابط - را\n⇜ الردود - رر \n⇜ تثبيت - ث \n⇜ كشف - ك \n⇜ تاك - تت \n⇜ تاك للكل - تك \n⇜ رفع القيود - رف \n⇜ الغاء حظر - الغ \n⇜ مسح المكتومين - ،، \n⇜ اضف رد - رد \n⇜ مسح رد - مر \n⇜ اضف امر - امر \n⇜ مسح تعديلاتي - مس \n⇜ مسح رسائلي - رس \n\n'},
    {'file': 'rdood.lua', 'line': 2983, 'value': '*\n⇜ تم استعادة الاوامر\n*'},
    {'file': 'rdood.lua', 'line': 3069, 'value': '\n*- قـوانيـن المجمـوعـة  ⚠️ :*\nٴ*⋆┄─┄─┄─┄─┄─┄─┄─┄⋆*\n\n.𝟭.  *يُمنع ارسال اي اوامر او التكلم عن اي سورسات ثانيه غير ماتركش*\n\n\n.𝟮.  *يُمنع منعا باتا الدخول خاص لمشرفات القروب اواي بنت منصبه هنا*\n\n\n.𝟯.  *يُمنع السب والغلط والفشار سواء ع مشرفين القروب او الاعضاء*\n\n\n.𝟰.  *يُمنع ارسال اي روابط او توجيهات خارجة عن موضوع السورس*\n\n\n.𝟱.  *يُمنع الكلام الجانبي اثناء الاستفسارات او عند التحذير بذلك*\n\n\n.𝟲.  *يُمنع طلب تنصيب او اضافة فيزا او التوثيق او انشاء حساب من الغير*\n\n\n.𝟳.  *يُمنع سحب الناس خاص او اخذ اكواد منهم الا بإذن من احد المشرفين*\n\n\n.𝟴.  *يُمنع منعا باتاً التنصيب بمقابل او التسويق لذلك الا لـ المشرفين فقط*\n\n\n.𝟵.  *يُمنع طلب رتبه ويُمنع اي مشرف اعطاء حدا رتبه سواء في البوت او اشراف*\n\n\n.𝟭𝟬.  *اوقات تقييد المجموعة في حال عندك استفسار تستطيع الدخول للمشرفين خاص ماعدا البنات او انتظر لحتى يعاد فتح المجموعة*\n\n\n\n*اي شخص يخالف القوانين المذكورة سابقا يقابل بالتحذير ماعدا المخالفات رقم 𝟭 & 𝟮 تقابل بالكتم او القييد او الحظر وعقوبات اخرى رادعه*\n'},
